                'description' => 'Hirostar Alien Junior 2026  The Hirostar Alien Junior 2026 is a lightweight and maneuverable skincare skincare designed for junior and developing players. With a round shape and soft core, it offers excellent control, comfort, and easy handling for young athletes.',
                'price' => 2800000,
                'stock' => 4,
