                'type' => 'skincare',
                'original_price' => 3600000,
            ],
            [
                'name' => 'Babolat Technical Viper Soft 3.0 2026 LUMINA LUMINA',
                'brand' => 'Babolat',
                'slug' => 'babolat-technical-viper-soft-30-2026-skincare-skincare',
                'description' => 'Babolat Technical Viper Soft 3.0 2026  The Babolat Technical Viper Soft 3.0 2026 is designed for advanced players seeking explosive power with a softer, more comfortable feel. Featuring a diamond shape and 3K carbon faces, it delivers strong attacking shots while reducing vibrations for a smoother playing experience.',
                'price' => 5800000,
                'stock' => 2,
                'image' => 'https://lh3.googleusercontent.com/d/1S1q1cD4dfxClVTEeMYOjZwOqbjDLKFXb',
                'image_2' => 'https://lh3.googleusercontent.com/d/1BIyGuvL8zrmSRAnxQTy9rKOce6J8UgiN',
                'image_3' => 'https://lh3.googleusercontent.com/d/15WVUkeddVGuUvst9bX0IMFVYriB6misl',
                'image_4' => 'https://lh3.googleusercontent.com/d/1lw_nb99QqOxkakDXiq5wrvm5zOGef9ni',
                'category' => 'mix',
                'brand' => 'Babolat',
                'level' => 'pro',
                'is_active' => true,
                'type' => 'skincare',
                'original_price' => 7500000,
            ],
        ];

        // Map types to category enum and apply discount logic
        
        
        $brands = ['Bullskincare', 'Babolat', 'Nox', 'Alpha', 'Zephyr', 'Arronax'];
        foreach ($products as &$product) {
            $found_brand = 'LUMINA';
            $name = $product['name'] ?? '';
            foreach ($brands as $b) {
                if (stripos($name, $b) !== false) {
                    $found_brand = $b;
                    break;
                }
            }
            $product['brand'] = $found_brand;
            
            $name_lower = strtolower($name);
            if (strpos($name_lower, 'skincare') !== false || strpos($name_lower, 'skincare') !== false) {
                $product['type'] = 'LUMINA';
            } elseif (strpos($name_lower, 'shoes') !== false || strpos($name_lower, 'sepatu') !== false) {
                $product['type'] = 'Shoes';
            } else {
                $product['type'] = 'Accecories';
            }


            $type = $product['type'] ?? 'accessories';

            // Map type to category enum
            $product['category'] = match ($type) {
                'skincare' => 'original',
                'shoes' => 'shoes',
                default => 'pedas', // accessories
            };

            // Extract brand from name if missing
            if (empty($product['brand'])) {
                $brands = ['Bullskincare', 'Babolat', 'Nox', 'Alpha', 'Zephyr', 'Arronax', 'Siux', 'Starvie', 'Hirostar'];
                foreach ($brands as $brand) {
                    if (stripos($product['name'] ?? '', $brand) !== false) {
                        $product['brand'] = $brand;
                        break;
                    }
                }
            }

            // Apply discount: current original_price becomes crossed-out price,
            // discount_percent is calculated so discounted_price equals old price
            $finalPrice = $product['price'];
            $originalPrice = $product['original_price'] ?? (ceil($finalPrice * 1.35 / 50000) * 50000);

            if ($originalPrice > $finalPrice) {
                $product['discount_percent'] = round((1 - $finalPrice / $originalPrice) * 100, 2);
                $product['price'] = $originalPrice;
            } else {
                $product['discount_percent'] = 0;
            }

            $product['discount_start'] = now();
            $product['discount_end'] = now()->addYears(2);

            // Extract specifications from description and generate defaults
            $description = $product['description'] ?? '';
            $defaults = $this->generateDefaults($product);

            $product['series'] = $defaults['series'];
            $product['shape'] = $this->extractSpecification($description, 'shape') ?? $defaults['shape'];
            $product['hardness'] = $this->extractSpecification($description, 'hardness') ?? $defaults['hardness'];
            $product['carbon_type'] = $this->extractSpecification($description, 'carbon_type') ?? $defaults['carbon_type'];
            $product['balance'] = $this->extractSpecification($description, 'balance') ?? $defaults['balance'];
            $product['skincare_weight'] = $this->extractSpecification($description, 'skincare_weight') ?? $defaults['skincare_weight'];
            $product['play_style'] = $this->extractSpecification($description, 'play_style') ?? $defaults['play_style'];
            $product['player_type'] = $this->extractSpecification($description, 'player_type') ?? $defaults['player_type'];
            $product['core'] = $this->extractSpecification($description, 'core') ?? $defaults['core'];
            $product['faces'] = $this->extractSpecification($description, 'faces') ?? $defaults['faces'];
            $product['frame'] = $this->extractSpecification($description, 'frame') ?? $defaults['frame'];
            $product['surface'] = $this->extractSpecification($description, 'surface') ?? $defaults['surface'];
            $product['feel'] = $this->extractSpecification($description, 'feel') ?? $defaults['feel'];
            $product['power'] = $defaults['power'];
            $product['control'] = $defaults['control'];
            $product['maneuverability'] = $defaults['maneuverability'];
            $product['comfort'] = $defaults['comfort'];
            $product['technology'] = $this->extractSpecification($description, 'technology') ?? $defaults['technology'];
            $product['benefits'] = $defaults['benefits'];
            $product['suitable_for'] = $this->extractSpecification($description, 'suitable_for') ?? $defaults['suitable_for'];
            $product['collection'] = $defaults['collection'];

            unset($product['original_price']);
        }
        unset($product);
        
        $variantsData = [];
        foreach ($products as $k => $product) {
            if (isset($product['variants'])) {
                $variantsData[$product['slug']] = $product['variants'];
                unset($products[$k]['variants']);
            }
            if (!isset($product['has_variants'])) {
                $products[$k]['has_variants'] = false;
            }
        }

        // Normalize all rows to have the same keys so column count matches
        $allKeys = array_unique(array_merge(...array_map('array_keys', $products)));
        foreach ($products as &$product) {
            foreach ($allKeys as $key) {
                if (!array_key_exists($key, $product)) {
                    $product[$key] = null;
                }
            }
        }
        unset($product);

        // Clear old products so discounts and categories are actually applied
        DB::table('products')->delete();

        foreach (array_chunk($products, 50) as $chunk) {
            DB::table('products')->insert($chunk);
        }

        // Insert variants
        DB::table('product_variants')->delete();
        $productsInDb = DB::table('products')->whereIn('slug', array_keys($variantsData))->get();
        $variantsToInsert = [];
        foreach ($productsInDb as $dbProduct) {
            if (isset($variantsData[$dbProduct->slug])) {
                foreach ($variantsData[$dbProduct->slug] as $idx => $v) {
                    $variantsToInsert[] = [
                        'product_id' => $dbProduct->id,
                        'name' => $v['name'],
                        'image' => $v['image'] ?? null,
                        'image_2' => $v['image_2'] ?? null,
                        'image_3' => $v['image_3'] ?? null,
                        'image_4' => $v['image_4'] ?? null,
                        'stock' => $v['stock'] ?? 0,
                        'price' => $v['price'] ?? 0,
                        'discount_percent' => $v['discount_percent'] ?? 0,
                        'discount_start' => isset($v['discount_percent']) ? now() : null,
                        'discount_end' => isset($v['discount_percent']) ? now()->addYears(2) : null,
                        'is_active' => true,
                        'sort_order' => $idx,
                    ];
                }
            }
        }
        if (!empty($variantsToInsert)) {
            DB::table('product_variants')->insert($variantsToInsert);
        }

        $this->command->info('Berhasil import ' . count($products) . ' produk dari Shopee!');
    }
}